   core=d/'input.core.json';subjectfile=d/'subject.json';run(compiler,'emit-core',source,'-o',core);run(compiler,'emit-semantic',core,'--core','-o',subjectfile);subject=read(subjectfile);unit=dict(folder=d,core=core,subject=subject,type=t);units[task]=unit
   witness=[r for r in fresh if r['role']=='definition_bound_source_deployment'and r['name']==task+'_modular_reconstruction'];assert len(witness)==1
