   for frame in sorted((FROZEN/'checks'/task).glob('args-*.json')):
    value=read(frame);actual=json.loads(run(compiler,'run',selected,task,frame,'--core').stdout);assert actual==expected(task,value);count+=1
   oldrecords.append(dict(id=row['id'],task=task,frames=count))
