  assert len(state)==42;review['nonzero_state_checks']=state
  stage='semantic false controls';negative=[]
  for view in sorted((FROZEN/'false').glob('*/view.json')):
   hashes[str(view)]=sha(view);p=run(compiler,'knowledge-check',dummycore,view,allow_failure=True);assert p.returncode!=0;negative.append(dict(view=str(view),exit_code=p.returncode,stderr=p.stderr))
  assert len(negative)==2;review['semantic_false_controls']=negative
  stage='helper context tamper'
  task='pipeline32_paired_prefix_add_heldout_u32';u=units[task];core=read(u['core']);next(f for f in core['program']['functions']if f['name']=='left_word')['body']={'Num':1};path=out/'tamper/input.core.json';encoded(path,core);subject=out/'tamper/subject.json';run(compiler,'emit-semantic',path,'--core','-o',subject);selection=read(u['folder']/'fresh/selection.json');selection['input_core_sha256']=read(subject)['input_core_sha256'];sel=out/'tamper/selection.json';encoded(sel,selection);p=run(compiler,'check-selection',path,sel,allow_failure=True);assert p.returncode!=0;review['correctly_rehashed_context_mismatch']=dict(exit_code=p.returncode,stderr=p.stderr)
