    effect=versions['prior']['core_sha256']!=versions['checked']['core_sha256'];uses_new=bool(set(versions['checked']['roots'])&removed);results.append(dict(task=task,versions=versions,additional_body_effect=effect,current_uses_fresh32=uses_new,interpretation='Additional checked32 body change on this merged catalogue.'if effect else'No additional32 proof effect: same selected merged-core bytes; upstream/old opportunities may already reach the target.'))
